const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";

let accessToken: string | null = null;

export function setAccessToken(token: string | null) {
  accessToken = token;
}

export function getAccessToken() {
  return accessToken;
}

async function refresh(): Promise<boolean> {
  const res = await fetch(`${API_URL}/auth/refresh`, {
    method: "POST",
    credentials: "include",
  });

  if (!res.ok) return false;

  const body = await res.json();
  accessToken = body.accessToken;
  return true;
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    ...((init?.headers as Record<string, string>) ?? {}),
  };

  if (accessToken) {
    headers["Authorization"] = `Bearer ${accessToken}`;
  }

  let res = await fetch(`${API_URL}${path}`, {
    ...init,
    credentials: "include",
    headers,
  });

  if (res.status === 401) {
    const refreshed = await refresh();
    if (refreshed && accessToken) {
      headers["Authorization"] = `Bearer ${accessToken}`;
      res = await fetch(`${API_URL}${path}`, {
        ...init,
        credentials: "include",
        headers,
      });
    }
  }

  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.message ?? `Request failed (${res.status})`);
  }

  return (await res.json()) as T;
}

export interface User {
  id: string;
  name: string;
  email: string;
}

export const authApi = {
  signup: (input: { name: string; email: string; password: string }) =>
    request<{ user: User; accessToken: string }>("/auth/signup", {
      method: "POST",
      body: JSON.stringify(input),
    }),
  login: (input: { email: string; password: string }) =>
    request<{ user: User; accessToken: string }>("/auth/login", {
      method: "POST",
      body: JSON.stringify(input),
    }),
  logout: () => request<{ message: string }>("/auth/logout", { method: "POST" }),
  me: () => request<User>("/auth/me"),
};

import { z } from "zod";

export const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
});

export const signupSchema = z.object({
  name: z.string().min(1),
  email: z.string().email(),
  password: z.string().min(8),
});

export type LoginInput = z.infer<typeof loginSchema>;
export type SignupInput = z.infer<typeof signupSchema>;

"use server";

import { authApi, setAccessToken } from "@/lib/auth/api";
import { loginSchema, signupSchema } from "@/lib/auth/validation";

export async function loginAction(formData: FormData) {
  const parsed = loginSchema.safeParse({
    email: formData.get("email"),
    password: formData.get("password"),
  });

  if (!parsed.success) {
    return { error: "Invalid credentials" };
  }

  try {
    const { user, accessToken } = await authApi.login(parsed.data);
    setAccessToken(accessToken);
    return { user };
  } catch (error) {
    return { error: (error as Error).message };
  }
}

export async function signupAction(formData: FormData) {
  const parsed = signupSchema.safeParse({
    name: formData.get("name"),
    email: formData.get("email"),
    password: formData.get("password"),
  });

  if (!parsed.success) {
    return { error: "Invalid input" };
  }

  try {
    const { user, accessToken } = await authApi.signup(parsed.data);
    setAccessToken(accessToken);
    return { user };
  } catch (error) {
    return { error: (error as Error).message };
  }
}

export async function logoutAction() {
  try {
    setAccessToken(null);
    await authApi.logout();
    return { success: true };
  } catch (error) {
    return { error: (error as Error).message };
  }
}

export async function meAction() {
  try {
    const user = await authApi.me();
    return { user };
  } catch (error) {
    return { error: (error as Error).message };
  }
}
